      el.style.cssText = "left:" + (x - d / 2).toFixed(1) + "px;top:" + (y - d / 2).toFixed(1) + "px;width:" + d.toFixed(1) + "px;height:" + d.toFixed(1) + "px";
      el.innerHTML = coinSVG(i * 5 + Math.floor(rnd() * 3));
      cv.insertBefore(el, cv.firstChild);
      coins.push({ el: el, d: d, bx: cx - x, by: cy - y, rot: rnd() * 0, ph: rnd() * 6.283, ph2: rnd() * 6.283, sp: .6 + rnd() * .7, bl: .42 + rnd() * .18, bd: .55 + Math.hypot(x - cx, y - cy) / Math.hypot(W / 2, H / 2) * .35, spin: (rnd() < .5 ? -1 : 1) * (140 + rnd() * 160) });
